import type { Metadata } from "next";
import { Inter, Outfit } from "next/font/google";
import "@/styles/globals.css";
import SmoothScroll from "@/components/layout/SmoothScroll";
import Navbar from "@/components/layout/Navbar";
import Footer from "@/components/layout/Footer";
import CustomCursor from "@/components/layout/CustomCursor";
import CookieConsent from "@/components/layout/CookieConsent";
import { cn } from "@/lib/utils";

const inter = Inter({ subsets: ["latin"], variable: "--font-inter" });
const outfit = Outfit({ subsets: ["latin"], variable: "--font-outfit" });

export const metadata: Metadata = {
  title: "Webkaro | Professional Web Development Agency in Noida",
  description: "Webkaro is a premium web development agency in Noida engineering high-performance, scalable websites and web applications for startups and enterprises.",
  keywords: ["Web Development Agency Noida", "Best IT Services Noida", "Next.js Development India", "SaaS MVP Development", "Software Development Company"],
  authors: [{ name: "Webkaro Team" }],
  creator: "Webkaro",
  publisher: "Webkaro",
  formatDetection: {
    email: false,
    address: false,
    telephone: false,
  },
  openGraph: {
    title: "Webkaro | Premium Web Development Agency",
    description: "Engineering scalable digital experiences for the modern web.",
    url: "https://webkaro.in",
    siteName: "Webkaro",
    images: [
      {
        url: "/og-image.jpg",
        width: 1200,
        height: 630,
        alt: "Webkaro Digital Agency",
      },
    ],
    locale: "en_IN",
    type: "website",
  },
  twitter: {
    card: "summary_large_image",
    title: "Webkaro | Premium Web Development",
    description: "High-performance websites and web applications.",
    images: ["/og-image.jpg"],
    creator: "@webkaro_dev",
  },
  robots: {
    index: true,
    follow: true,
    googleBot: {
      index: true,
      follow: true,
      'max-video-preview': -1,
      'max-image-preview': 'large',
      'max-snippet': -1,
    },
  },
  alternates: {
    canonical: "https://webkaro.in",
  },
};

const jsonLd = {
  "@context": "https://schema.org",
  "@type": "Organization",
  "name": "Webkaro",
  "url": "https://webkaro.in",
  "logo": "https://webkaro.in/logo.png",
  "description": "Premium web development agency specializing in Next.js and high-performance digital solutions.",
  "address": {
    "@type": "PostalAddress",
    "streetAddress": "Sector 62",
    "addressLocality": "Noida",
    "addressRegion": "Uttar Pradesh",
    "postalCode": "201301",
    "addressCountry": "IN"
  },
  "contactPoint": {
    "@type": "ContactPoint",
    "telephone": "+91-98765-43210",
    "contactType": "customer service",
    "areaServed": "IN",
    "availableLanguage": ["en", "hi"]
  },
  "sameAs": [
    "https://twitter.com/webkaro_dev",
    "https://linkedin.com/company/webkaro",
    "https://instagram.com/webkaro.tech"
  ]
};

import { ThemeProvider } from "@/components/layout/ThemeProvider";
import { Toaster } from "react-hot-toast";
import AnoAI from "@/components/ui/animated-shader-background";
import GlobalFloatingButton from "@/components/ui/global-floating-button";

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en" suppressHydrationWarning>
      <body
        className={cn(
          inter.variable,
          outfit.variable,
          "min-h-screen bg-black text-foreground font-sans antialiased transition-colors duration-300 overflow-x-hidden"
        )}
      >
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
        />
        <ThemeProvider
          attribute="class"
          defaultTheme="dark"
          enableSystem
          disableTransitionOnChange
        >
          <div className="fixed inset-0 -z-10 bg-black">
            <AnoAI />
          </div>
          <SmoothScroll>
            <a href="#main-content" className="skip-link">Skip to main content</a>
            <CustomCursor />
            <Navbar />
            <main id="main-content" className="relative flex flex-col min-h-screen z-10">
              {children}
            </main>
            <Footer />
            <CookieConsent />
            <GlobalFloatingButton />
            <Toaster position="top-right" />
          </SmoothScroll>
        </ThemeProvider>
      </body>
    </html>
  );
}
